<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Convocation {{ $application->candidate_number }}</title><style>body{font-family:Arial,sans-serif;color:#14214d;margin:0}.sheet{max-width:800px;margin:30px auto;padding:50px;border:2px solid #2b2c89}.head{text-align:center;border-bottom:3px solid #f0c84b;padding-bottom:25px}.head img{width:80px}.title{text-align:center;margin:45px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.box{padding:14px;background:#f3f6fa}.instructions{margin-top:30px;padding:20px;border-left:4px solid #2b2c89;background:#f8f9fb}.actions{text-align:center;margin:20px}@media print{.actions{display:none}.sheet{border:0;margin:0;max-width:none}}@media(max-width:600px){.grid{grid-template-columns:1fr}.sheet{margin:0;padding:25px}}</style></head><body><div class="actions"><button onclick="window.print()">Imprimer / Enregistrer en PDF</button></div><main class="sheet"><header class="head"><img src="{{ $siteMedia->get('site_logo','/assets/images/insg-logo.jpeg') }}" alt="INSG"><h2>INSTITUT NATIONAL DES SCIENCES DE GESTION</h2><p>République Gabonaise</p></header><div class="title"><h1>CONVOCATION AU CONCOURS</h1><p>{{ $application->contest->title }} — {{ $application->contest->academic_year }}</p></div><div class="grid"><div class="box"><strong>Matricule</strong><br>{{ $application->candidate->registration_number }}</div><div class="box"><strong>Numéro de candidat</strong><br>{{ $application->candidate_number }}</div><div class="box"><strong>Candidat</strong><br>{{ $application->candidate->last_name }} {{ $application->candidate->first_names }}</div><div class="box"><strong>Date et heure</strong><br>{{ $application->contest->exam_date->format('d/m/Y') }} à {{ substr($application->contest->exam_time,0,5) }}</div><div class="box"><strong>Lieu</strong><br>{{ $application->contest->location }}</div><div class="box"><strong>Référence</strong><br>{{ $application->contest->reference }}</div></div><div class="instructions"><strong>Instructions</strong><p>{{ $application->contest->additional_information ?: 'Présentez-vous 30 minutes avant le début du concours avec cette convocation et une pièce d’identité en cours de validité.' }}</p></div></main></body></html>
